# SOLUTION 4: Fibonacci with Limit
def fibonacci_limit_solution(max_value):
    a, b = 0, 1
    while a <= max_value:
        yield a
        a, b = b, a + b

# SOLUTION 5: File Line Counter
def read_lines_with_numbers_solution(filename):
    with open(filename, "r") as file:
        for line_num, line in enumerate(file, 1):
            yield (line_num, line.strip())

# SOLUTION 6: Infinite Cycle
def cycle_solution(iterable):
    saved = []
    for item in iterable:
        yield item
        saved.append(item)
    while saved:
        for item in saved:
            yield item

# SOLUTION 7: Generator Pipeline
def read_numbers_solution(numbers):
    for num in numbers:
        yield num

def filter_positive_solution(numbers):
    for num in numbers:
        if num > 0:
            yield num

def square_solution(numbers):
    for num in numbers:
        yield num**2

# SOLUTION 8: Batching Generator
def batch_solution(iterable, batch_size):
    batch_list = []
    for item in iterable:
        batch_list.append(item)
        if len(batch_list) == batch_size:
            yield batch_list
            batch_list = []
    if batch_list:
        yield batch_list

# SOLUTION 9: Prime Number Generator
def primes_solution(n):
    count = 0
    num = 2
    while count < n:
        if is_prime(num):
            yield num
            count += 1
        num += 1

# SOLUTION 10: Flatten Nested Lists
def flatten_solution(nested_list):
    for item in nested_list:
        if isinstance(item, list):
            yield from flatten_solution(item)
        else:
            yield item
