# BONUS SOLUTION 1: Moving Average
def moving_average_solution(data, window_size):
    data_list = list(data)
    for i in range(len(data_list) - window_size + 1):
        window = data_list[i : i + window_size]
        yield sum(window) / window_size

# BONUS SOLUTION 2: Generator with State
def stateful_counter_solution():
    count = 0
    while True:
        value = yield count
        if value == "reset":
            count = 0
        elif value is not None:
            count += value

# BONUS SOLUTION 3: Permutations Generator
def permutations_solution(s):
    if len(s) <= 1:
        yield s
    else:
        for i, char in enumerate(s):
            remaining = s[:i] + s[i + 1 :]
            for perm in permutations_solution(remaining):
                yield char + perm
